"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "Lũ chó vừa đi, đám cáo đã lảng vảng quanh chuồng. Đuổi chúng về đồng cỏ",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "Lợn rừng ăn sạch mùa màng của nông dân. Một mùa đông không lương thực sẽ là dấu chấm hết",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "Ở rìa đồng cỏ có một viên Đá Phẫn Nộ đang rực sáng. Cơn giận của nó khiến thú dữ phát cuồng – đập vỡ nó",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "May mà Bao cử bạn tới. Thổ phỉ cướp mọi thương nhân trên đường rừng. Đuổi chúng đi",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "Lợn rừng ở đây có gai thay cho lông. Chúng xé nát bẫy của chúng ta – cả người đặt bẫy",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "Sâu trong rừng, nhện khổng lồ giăng tơ khắp lối đi. Đốt sạch nếu cần",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "Giữa rừng mọc lên một viên Đá Gai. Dây gai của nó bóp nghẹt mọi cây. Phá hủy nó",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "Hagen cử bạn tới à? Vậy đi thôi, lũ orc đã ở trước hàng rào. Làm suy yếu đạo quân của chúng",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "Lũ orc nuôi linh cẩu như chó và thả chúng vồ trinh sát của ta. Dọn sạch bầy đó",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "Idris cử bạn tới à? Thần linh ưu ái Sahra. Rắn hổ mang rình rập ở mọi nguồn nước",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "Nghe tiếng lắc rắc không? Rắn chuông. Hàng trăm con. Các đoàn lữ hành không dám lên đường nữa",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "Trên Đỉnh Băng Giá có người thấy người tuyết to như nhà. Mang da chúng về làm bằng chứng",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "Voi ma mút phát cuồng từ khi băng giá không tan. Chúng giẫm nát kho lương của ta",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Nơi Đá Tĩnh Lặng đứng, mọi khúc ca đều câm lặng. Hãy mang âm thanh trở lại đỉnh núi",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "Viên cuối cùng và mạnh nhất trong mọi Đá Linh Hồn. Phá hủy nó, các viên đá sẽ ngừng lớn lên",
"Hunde aus der Asche": "Lũ Chó Từ Tro Tàn",
"Diebe im Zwielicht": "Kẻ Trộm Trong Chạng Vạng",
"Wölfe aus dem Nebel": "Bầy Sói Từ Sương Mù",
"Die bleichen Geweihe": "Những Chiếc Gạc Nhợt Nhạt",
"Nachthirsche rennen mit leuchtenden Geweihen gegen unsere Zäune, als jage sie etwas. Halte sie auf": "Hươu đêm với gạc phát sáng lao vào hàng rào như bị thứ gì đuổi. Ngăn chúng lại",
"Die Leitwölfe": "Những Con Đầu Đàn",
"Jedes Nebelrudel folgt einem Nachtleitwolf. Ohne ihn zerstreut sich das Rudel im Dunst": "Mỗi bầy sói sương mù đi theo một con đầu đàn đêm. Không có nó, cả bầy tan tác trong màn sương",
"Keiler im Mondkraut": "Lợn Rừng Trong Cỏ Trăng",
