"Glühende Hauer": "Nanh Rực Lửa",
"Die Keiler hier tragen Glut im Borstenkamm. Wo sie sich reiben, fängt das Unterholz Feuer": "Lợn rừng ở đây mang than hồng trên bờm. Chúng cọ vào đâu, bụi cây bén lửa ở đó",
"Schützen im Rauch": "Cung Thủ Trong Khói",
"Aus dem Rauch schießen Rußschützen, bevor man sie sieht. Hol sie aus den verbrannten Kronen": "Cung thủ bồ hóng bắn ra từ màn khói trước khi bị nhìn thấy. Lôi chúng ra khỏi những tán cây cháy",
"Graue Netze": "Mạng Nhện Xám",
"Zwei Steine der Gier locken die Räuber an wie Glut die Motten. Zerschlage sie": "Hai viên Đá Tham Lam thu hút kẻ cướp như than hồng hút thiêu thân. Đập vỡ chúng",
"Rußgraue Jäger": "Thợ Săn Xám Bồ Hóng",
"Rußluchse sind in der Asche unsichtbar. Unsere Köhler kommen nicht mehr heim. Sei wachsamer als sie": "Linh miêu bồ hóng vô hình trong tro. Thợ đốt than của ta không còn trở về. Hãy cảnh giác hơn chúng",
"Kohlenbären": "Gấu Than",
"Knochen im Sand": "Xương Trong Cát",
"Ascan schickt dich? Dann komm, die Beinbrecher stehen schon vor unserem Ring. Brich ihre Reihen": "Ascan cử bạn tới à? Vậy đi thôi, lũ bẻ xương đã ở trước vòng thành. Phá vỡ hàng ngũ chúng",
"Aashyänen": "Linh Cẩu Ăn Xác",
"Die Hyänen folgen den Beinbrechern und fressen, was diese liegen lassen. Erledige die Meute": "Linh cẩu theo sau lũ bẻ xương và ăn những gì chúng bỏ lại. Dọn sạch bầy đó",
"Die Knochenruferinnen": "Những Kẻ Gọi Xương",
"Die Ruferinnen singen die Gebeine aus dem Sand. Ohne ihren Gesang bleiben die Toten liegen": "Những kẻ gọi xương cất tiếng hát kéo hài cốt khỏi cát. Không có tiếng hát, người chết sẽ nằm yên",
"Zwei schwarze Steine ragen aus den Dünen, und die Knochen sammeln sich darum. Nimm ihnen ihre Mitte": "Hai viên đá đen nhô lên khỏi cồn cát, xương cốt tụ quanh chúng. Hãy tước đi trung tâm của chúng",
"Bleiche Stachel": "Ngòi Nhợt Nhạt",
"Die Knochenhauptmänner": "Những Đội Trưởng Xương",
"Die Beinbrecher gehorchen Hauptmännern in alten Rüstungen. Fällst du sie, zerfällt das Heer": "Lũ bẻ xương nghe lệnh những đội trưởng mặc giáp cũ. Hạ chúng, đạo quân sẽ tan rã",
"Ein Stein der Asche verbrennt die Wüste von innen. Lösch ihn aus, bevor nur Staub bleibt": "Một viên Đá Tro thiêu đốt sa mạc từ bên trong. Dập tắt nó trước khi chỉ còn lại bụi",
"Rot am Horizont": "Màu Đỏ Nơi Chân Trời",
"Ossian hat recht, dich zu schicken. Blutoger stampfen jede Nacht gegen unsere Inseln. Halte sie fern": "Ossian cử bạn tới là đúng. Ogre máu mỗi đêm đều tấn công các đảo của ta. Giữ chúng tránh xa",
"Wargrudel der Steppe": "Bầy Warg Thảo Nguyên",
"Steppenwargs jagen in großen Rudeln durch das rote Gras. Jag das Rudel, bevor es uns jagt": "Warg thảo nguyên săn mồi theo bầy lớn trong cỏ đỏ. Săn cả bầy trước khi chúng săn chúng ta",
"Blutdämonen": "Quỷ Máu",
"Aus den roten Tümpeln steigen Blutdämonen. Treib sie zurück in die Tiefe": "Quỷ máu trồi lên từ những vũng đỏ. Đẩy chúng trở lại vực sâu",
"Die Steine der Glut heizen die Tümpel auf, bis sie kochen. Lösche sie aus": "Những viên Đá Than Hồng nung nóng vũng nước đến sôi sục. Dập tắt chúng",
"Blutmäuler": "Mồm Máu",
"Blutmäuler bewachen die Tümpel der Dämonen. Wer sie besiegt, kann den Quellen nahe kommen": "Mồm Máu canh giữ vũng nước của lũ quỷ. Ai hạ được chúng mới tới gần được nguồn",
"Die Klippenfeste": "Pháo Đài Vách Đá",
"Kobras im Fels": "Rắn Hổ Mang Trong Đá",
"Das Rasseln in der Nacht": "Tiếng Lắc Rắc Trong Đêm",
"Hörst du das Rasseln an den Klippen? Nachtrassler. Hunderte. Keiner traut sich mehr auf die Pfade": "Nghe tiếng lắc rắc trên vách đá không? Rắn chuông đêm. Hàng trăm con. Chẳng ai dám đi đường mòn nữa",
"Moorpythons": "Trăn Đầm Lầy",
"Im Schwarzmoor würgen Pythons ganze Boote unter Wasser. Wer dort Torf sticht, kommt nicht wieder": "Trong Đầm Lầy Đen, trăn siết cả con thuyền xuống nước. Ai đi cắt than bùn ở đó không bao giờ trở lại",
"Panther im Nebel": "Báo Trong Sương Mù",
"Die Nebelpanther jagen für die Moornagas. Mach das Moor wieder sicher": "Báo sương mù săn mồi cho naga đầm lầy. Hãy làm đầm lầy an toàn trở lại",
"Die lange Nacht": "Đêm Dài",
"Mitternachtswölfe": "Sói Nửa Đêm",
"Ysra hat dich geschickt? Gut. Mitternachtswölfe umkreisen die Terrassen, sie riechen jede Schwäche": "Ysra cử bạn tới à? Tốt. Sói nửa đêm đang vây quanh các bậc thềm, chúng đánh hơi được mọi điểm yếu",
"Der Dunkelyeti": "Người Tuyết Bóng Đêm",
"Dunkelyetis kommen nachts die Hänge herunter, so groß wie Hütten. Bring ihre Felle als Beweis": "Người tuyết bóng đêm xuống sườn núi vào ban đêm, to như túp lều. Mang da chúng về làm bằng chứng",
"Zwei Steine des Frostes halten die Nacht fest. Zerschlage sie": "Hai viên Đá Băng Giá đang giữ chặt màn đêm. Đập vỡ chúng",
"Nachtmammuts": "Voi Ma Mút Đêm",
"Die Nachtmammuts sind rasend, seit kein Morgen mehr kommt. Sie zertrampeln unsere Vorratshütten": "Voi ma mút đêm phát cuồng từ khi bình minh không tới nữa. Chúng giẫm nát kho lương của ta",
"Frostgespenster": "Bóng Ma Băng Giá",
"In der Nacht wandern Gespenster aus Reif. Wer sie berührt, erfriert von innen": "Ban đêm, bóng ma sương muối lang thang. Ai chạm vào chúng sẽ đóng băng từ bên trong",
"Wo der Stein der Stille steht, verstummt sogar der Wind. Bring den Klang zurück": "Nơi Đá Tĩnh Lặng đứng, đến gió cũng câm lặng. Hãy mang âm thanh trở lại",
"Heimkehr nach Mondfall": "Trở Về Trăng Rơi",
"Allein oder mit der Gruppe in die Arena – und mit vollen Taschen zurück": "Một mình hoặc theo tổ đội vào đấu trường – và trở về với túi đầy",
"Ehre gewinnt man nur gegen echte Gegner": "Danh dự chỉ có được khi đấu với đối thủ thật sự",
"Bronze ist nur der Anfang": "Đồng chỉ là khởi đầu",
"Aufwertung": "Nâng cấp",
"Diese Auktion gibt es nicht mehr": "Phiên đấu giá này không còn nữa",
"Das hat gerade jemand anderes gekauft": "Người khác vừa mua mất rồi",
"Diese Auktion ist schon beendet": "Phiên đấu giá này đã kết thúc",
"Diese Auktion ist abgelaufen": "Phiên đấu giá này đã hết hạn",
"Eigene Angebote kannst du nicht kaufen": "Bạn không thể mua món hàng của chính mình",
